class BlankNodeOrderSpillIdentityTest {
	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();

	@Test
	void trustedRemoteAliasesRetainTransportAuthorityAfterActualSpill() {
		for (boolean nested : List.of(false, true)) {
			Object epoch = new Object();
			var scope = new BlankNodeAllocationScope();
			try (var active = scope.activate()) {
				var context = new QueryEvaluationContext.Minimal(null);
				Value alias = RemoteBNode.newResponseScope(scope, VF, epoch, true).map(VF.createBNode("canonical"));
				Value original = nested ? VF.createTripleTerm(VF.createIRI("urn:s"), VF.createIRI("urn:p"), alias)
						: alias;
				Value canonical = nested
						? VF.createTripleTerm(VF.createIRI("urn:s"), VF.createIRI("urn:p"), VF.createBNode("canonical"))
						: VF.createBNode("canonical");
				var input = new ArrayList<BindingSet>();
				for (int key : List.of(3, 1, 2)) {
					var row = new MapBindingSet();
					row.addBinding("key", VF.createLiteral(key));
					row.addBinding("value", original);
					input.add(row);
				}
				var comparator = comparator(context, "key");
				long[] spills = { 0 };
				try (var rows = new OrderIterator(new CloseableIteratorIteration<>(input.iterator()), comparator,
						Long.MAX_VALUE, false, 1) {
					@Override
					protected void onSpillToDisk(int count, long bytes) {
						spills[0]++;
					}
				}) {
					while (rows.hasNext()) {
						Value restored = rows.next().getValue("value");
						assertEquals(canonical, RemoteBNode.toRemoteValue(restored, epoch, true, true));
					}
				}
				assertTrue(spills[0] > 0, "the identity check must execute after a physical serialized spill");
			}
		}
	}

	@Test
	void duplicateMappingsKeepDistinctLabelledOccurrencesAcrossSpill() {
		var context = new QueryEvaluationContext.Minimal(null);
		BindingSet reused = EmptyBindingSet.getInstance();
		var input = new CloseableIteratorIteration<>(List.of(reused, reused, reused).iterator());
		var extension = new ExtensionIterator(input,
				row -> row.setBinding("node", context.getOrCreateBNode("label", row, VF)), context);
		var nodes = new ArrayList<Value>();
		try (var rows = new OrderIterator(extension, comparator(context, "node"), Long.MAX_VALUE, false, 1)) {
			while (rows.hasNext()) {
				BindingSet row = rows.next();
				Value node = row.getValue("node");
				assertEquals(node, context.getOrCreateBNode("label", row, VF));
				nodes.add(node);
			}
		}
		assertEquals(3, nodes.size());
		assertNotEquals(nodes.get(0), nodes.get(1));
		assertNotEquals(nodes.get(1), nodes.get(2));
	}

	private static OrderComparator comparator(QueryEvaluationContext context, String variable) {
		return new OrderComparator(mock(EvaluationStrategy.class),
				new Order(new SingletonSet(), new OrderElem(Var.of(variable))), new ValueComparator(), context);
	}

	@Test
	void comparatorEqualVisibleRowsRetainEachOccurrencesHiddenLabelState() {
		for (long spillThreshold : List.of(Long.MAX_VALUE, 1L)) {
			var context = new QueryEvaluationContext.Minimal(null);
			var input = new ArrayList<BindingSet>();
			var expected = new HashSet<Value>();
			for (int i = 0; i < 3; i++) {
				var row = new MapBindingSet();
				row.addBinding("key", VF.createLiteral(1));
				try (var ignored = context.getBlankNodeAllocationScope().beginSolutionOccurrence(row)) {
					expected.add(context.getOrCreateBNode("hidden", row, VF));
				}
				input.add(row);
			}
			assertEquals(3, expected.size());
			var actual = new HashSet<Value>();
			int count = 0;
			try (var rows = new OrderIterator(new CloseableIteratorIteration<>(input.iterator()),
					comparator(context, "key"), Long.MAX_VALUE, false, spillThreshold)) {
				while (rows.hasNext()) {
					BindingSet row = rows.next();
					actual.add(context.getOrCreateBNode("hidden", row, VF));
					count++;
				}
			}
			assertEquals(3, count);
			assertEquals(expected, actual,
					"equal visible rows retain their own hidden mapping state at spill threshold " + spillThreshold);
		}
	}
}
